root.innerHTML = `
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:12;stroke-linecap:round;opacity:0.4;">
    <path id="l0" d="M470 205 L470 255" />
    <path id="l1" d="M470 435 L470 485" />
    <path id="l2" d="M470 665 L470 715" />
  </svg>
  <div id="c0" style="${STY('var(--acc)')}top:25px;">ORGANIZE<br>LOCAL FILES</div>
  <div id="c1" style="${STY('var(--acc2)')}top:255px;">FILL DIGITAL<br>FORMS</div>
  <div id="c2" style="${STY('var(--acc)')}top:485px;">BUILD<br>SLIDESHOWS</div>
  <div id="c3" style="${STY('var(--acc2)')}top:715px;height:220px;font-size:62px;border:6px solid #fff">AUTONOMOUS<br>ASSISTANT</div>
`;

const cards = [0, 1, 2, 3].map(i => root.querySelector('#c' + i));
const lines = [0, 1, 2].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = p >= 0.55 ? d * 0.55 : t;

  // Cards Entrance with Springs
  const cardDelays = [0.1, 1.0, 1.9, 2.8];
  cards.forEach((el, i) => {
    const s = spr(tf, cardDelays[i], 0.8, 7);
    el.style.opacity = clamp(s * 2);
    const scale = lerp(0.8, 1, E_OUT(clamp(s)));
    const slide = lerp(50, 0, E_OUT(clamp(s)));
    el.style.transform = `translateY(${slide}px) scale(${scale})`;
  });

  // Connecting Lines Drawing
  const lineDelays = [0.7, 1.6, 2.5];
  lines.forEach((line, i) => {
    const pLine = clamp((tf - lineDelays[i]) * 2.5);
    line.el.style.strokeDashoffset = line.len * (1 - E_INOUT(pLine));
    line.el.style.opacity = pLine > 0 ? 0.4 : 0;
  });

  // Final Emphasis on Assistant
  const focus = spr(tf, 3.2, 0.9, 5);
  if (focus > 0) {
    cards[3].style.boxShadow = `0 0 ${lerp(40, 80, focus)}px ${lerp(0, 20, focus)}px color-mix(in srgb, var(--acc2) 40%, transparent), 0 26px 40px -14px rgba(0,0,0,.5), inset 0 4px 0 rgba(255,255,255,.5)`;
    cards[3].style.transform += ` scale(${lerp(1, 1.03, E_OUT(focus))})`;
  }
}
